mapper.select:
SELECT a.accommodation_no AS acmNo, a.accommodation_name AS acmName, a.accommodation_address AS acmAddress, a.accommodation_contents AS contents, a.checkin AS checkinTime, a.checkout AS checkoutTime, a.tel AS acmTel, a.keyword_no AS keywordNo, a.business_no AS businessNo, a.category_no AS categoryNo FROM accommodation a LEFT JOIN category c ON a.category_no = c.category_no LEFT JOIN keyword k ON a.keyword_no = k.keyword_no
WHERE (a.accommodation_name LIKE CONCAT ('%', #{search}, '%') OR a.tel LIKE CONCAT ('%', #{search}, '%'))
ORDER BY a.accommodation_no DESC LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO accommodation_amenities (
    accommodation_no,
    amenities_no
) VALUES (
    #{accommodationNo},
    #{amenitiesNo}
)

mapper.select:
SELECT amenities_no
FROM accommodation_amenities
WHERE accommodation_no = #{acmNo}
